// Confirmed execution is separate from the legacy registration/manual-history indicators.
const path=location.pathname.replace(/\.html$/,'').replace(/\/$/,'');
if(path==='/impacto'){
 const main=document.querySelector('main'),periodSelect=document.getElementById('impact-period');
 if(main){
  const el=(tag,text,className)=>{const item=document.createElement(tag);if(text!==undefined)item.textContent=text;if(className)item.className=className;return item;};
  if(!document.querySelector('link[data-confirmed-impact-styles]')){const styles=document.createElement('link');styles.rel='stylesheet';styles.href='/operations-admin.css';styles.dataset.confirmedImpactStyles='';document.head.append(styles);}
  const section=el('section',undefined,'section confirmed-impact-section'),wrap=el('div',undefined,'wrap');section.id='execucao-confirmada';wrap.append(el('div','DO ACOMPANHAMENTO À REALIZAÇÃO','eyebrow'),el('h2','Apoio realizado, com registro confirmado.'),el('p','Este quadro reúne os apoios realizados no CRM e na agenda. Pedidos recebidos e encaminhamentos ainda não representam atendimento. Uma pessoa com vários pedidos é contada uma vez no mês quando os cadastros estão ligados à mesma identidade. Os totais históricos complementares continuam separados.','confirmed-impact-note'));
  const status=el('p','Consultando execução confirmada…','confirmed-impact-status');status.setAttribute('role','status');status.setAttribute('aria-live','polite');const grid=el('div',undefined,'confirmed-impact-grid');wrap.append(status,grid);section.append(wrap);main.append(section);
  const labels={pessoas_apoiadas:['Pessoas apoiadas','Pessoas identificadas no CRM, contadas uma vez no mês, com apoio realizado.'],familias_apoiadas:['Famílias apoiadas','Famílias vinculadas ao apoio realizado, contadas uma vez no mês.'],atividades_realizadas:['Apoios realizados','Atividades e entregas confirmadas. Vínculos com a agenda evitam duplicar o mesmo evento.'],cestas_entregues:['Cestas entregues','Quantidade de cestas confirmadas nos serviços classificados como cesta básica.'],pecas_entregues:['Peças entregues','Quantidade confirmada nos serviços medidos em peças. Não representa número de pessoas.'],itens_entregues:['Itens entregues','Quantidade confirmada de itens e utensílios. Não representa número de pessoas.']};
  let generation=0;
  async function load(){const current=++generation,period=periodSelect?.value||new Date(Date.now()-3*60*60*1000).toISOString().slice(0,7);if(!/^20\d{2}-(0[1-9]|1[0-2])$/.test(period))return;status.textContent='Consultando execução confirmada…';try{const response=await fetch('/api/crm/impacto?periodo='+encodeURIComponent(period),{cache:'no-store'}),data=await response.json();if(!response.ok)throw Error();if(current!==generation)return;if([...Object.keys(labels),'cadastros_sem_identidade'].some(key=>!Number.isSafeInteger(data[key])||data[key]<0))throw Error();grid.replaceChildren();for(const[key,[title,hint]]of Object.entries(labels)){const card=el('article',undefined,'confirmed-impact-card');card.append(el('span',title),el('strong',new Intl.NumberFormat('pt-BR').format(data[key])),el('small',hint));grid.append(card);}status.textContent='Execução confirmada de '+new Date(period+'-02T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})+' · Atualizada pelo banco, sem dados pessoais. '+(data.cadastros_sem_identidade ? data.cadastros_sem_identidade+' cadastro(s) com apoio aguardam identificação e ainda não entram no total de pessoas.' : 'Cadastros com apoio neste período identificados no CRM.');}catch{if(current===generation){grid.replaceChildren();status.textContent='Não foi possível consultar a execução confirmada agora. Tente novamente mais tarde.';}}}
  periodSelect?.addEventListener('change',load);if(periodSelect)new MutationObserver(load).observe(periodSelect,{childList:true});window.addEventListener('focus',load);setInterval(()=>{if(!document.hidden)load();},60000);load();
 }
}
